document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('login-form');
  const errorMessage = document.getElementById('error-message');
  const logoutButton = document.getElementById('logout');
  const logoutLink = document.getElementById('logout-link');

  if (form) {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const username = form.username.value;
      const password = form.password.value;

      if (username === 'Riechelle' && password === 'itsmy21st') {
        localStorage.setItem('isLoggedIn', 'true');
        window.location.href = 'home/index.html';
      } else {
        errorMessage.style.display = 'block';
      }
    });
  }

  if (logoutButton) {
    logoutButton.addEventListener('click', () => {
      localStorage.removeItem('isLoggedIn');
      window.location.href = 'index.html';
    });
  }

  if (logoutLink) {
    logoutLink.addEventListener('click', (e) => {
      e.preventDefault();
      localStorage.removeItem('isLoggedIn');
      window.location.href = '../index.html';
    });
  }

  // Initialize Swiper for the footer
  const marqueeSwiper = document.querySelector('.marquee-swiper');
  if (marqueeSwiper) {
    const swiper = new Swiper('.marquee-swiper', {
      slidesPerView: 'auto',
      spaceBetween: 0,
      loop: true,
      speed: 2000,
      allowTouchMove: false,
      autoplay: {
        delay: 1,
        disableOnInteraction: false,
      },
    });
  } else {
    console.error('Swiper element not found.');
  }

  // Add header initialization if missing
  const header = document.querySelector('header');
  if (!header) {
    console.warn('Header element is missing. Please ensure it is present in the HTML.');
  }

  // Add script for burger nav functionality
  const burgerMenu = document.getElementById('burger-menu');
  const burgerNav = document.querySelector('.burger-nav');

  if (burgerMenu && burgerNav) {
    burgerMenu.addEventListener('click', () => {
      if (burgerNav.classList.contains('hidden')) {
        burgerNav.classList.remove('hidden'); // Show the entire nav
      } else {
        burgerNav.classList.add('hidden'); // Hide the entire nav
      }
    });
  }

  if (window.location.pathname.endsWith('home/index.html')) {
    ClickedMe();
  }
});

function createSparkleEffect(x, y) {
  const arr = [1, 0.9, 0.8, 0.5, 0.2];

  arr.forEach((i) => {
    const offset = (1 - i) * 75;
    const star = document.createElement('div');

    star.className = 'star';
    star.style.position = 'absolute'; // Ensure proper positioning
    star.style.top = `${y + Math.round(Math.random() * offset - offset / 2)}px`;
    star.style.left = `${x + Math.round(Math.random() * offset - offset / 2)}px`;

    document.body.appendChild(star);

    setTimeout(() => {
      if (star.parentElement) {
        star.parentElement.removeChild(star); // Ensure proper cleanup
      }
    }, Math.round(Math.random() * i * 600));
  });
}

function handleSparkleEvent(e) {
  const x = e.touches ? e.touches[0].clientX : e.pageX;
  const y = e.touches ? e.touches[0].clientY : e.pageY;
  createSparkleEffect(x, y);
}

window.addEventListener('mousemove', handleSparkleEvent, { passive: true });
window.addEventListener('touchmove', handleSparkleEvent, { passive: true });

function ClickedMe() {
  const container = document.createElement('div');
  container.id = 'clickableDiv';
  container.innerHTML = '<h1>Click me anywhere</h1>';

  const imageLinks = [
    'https://res.cloudinary.com/drkmgpcad/image/upload/v1724236655/20240522_223149_0000_oil3uj.png',
    'https://res.cloudinary.com/drkmgpcad/image/upload/v1723987464/cld-sample.jpg',
    'https://res.cloudinary.com/drkmgpcad/image/upload/v1723987463/samples/cup-on-a-table.jpg',
    // Add more image links as needed
  ];


  // Append the container to the main element
  const main = document.querySelector('main');
  if (main) {
    main.appendChild(container);
  } else {
    console.error('Main element not found.');
  }

  container.addEventListener('click', function (event) {
    // Get all existing images
    const images = this.querySelectorAll('img');

    // Remove the oldest image if there are already 5 or more images
    if (images.length >= 5) {
      images[0].remove();
    }

    // Create a new image element
    const img = document.createElement('img');

    // Randomly select an image from the list
    const randomImageLink = imageLinks[Math.floor(Math.random() * imageLinks.length)];
    img.src = randomImageLink;

    // Append the image to the clickable div
    this.appendChild(img);

    img.onload = () => {
      // Get the dimensions of the clickable div
      const divRect = this.getBoundingClientRect();

      // Get the dimensions of the image after it has been added to the DOM
      const imgRect = img.getBoundingClientRect();

      // Calculate the position of the image relative to the click
      let left = event.clientX - divRect.left; // Adjust for container position
      let top = event.clientY - divRect.top; // Adjust for container position

      // Ensure the image stays within the bounds of the clickable div
      if (left + imgRect.width > divRect.width) {
        left = divRect.width - imgRect.width;
      }

      if (top + imgRect.height > divRect.height) {
        top = divRect.height - imgRect.height;
      }

      // Set the image position
      img.style.left = `${left - 10}px`;
      img.style.top = `${top - 10}px`;
      img.style.position = 'absolute';

      // Add the 'show' class to trigger the fade-in and scale-up animation
      img.classList.add('show');
    };
  });

  return container;
}
